36:00Z", "source_utc_offset_minutes": 0}], "turn_id": "turn_59d2f5347cf943e1886e0fea96014628", "session_id": "session_692afd19c6ac4d4a8b1c535168bdb40e", "sequence": 89}, {"request_id": "dialogue-90", "events": [{"role": "user", "content": "Melanie: Sounds awesome, Caroline! Have a great time and learn a lot. Have fun!", "speaker": "Melanie", "occurred_at": "2023-07-03T13:36:00Z", "source_utc_offset_minutes": 0}], "turn_id": "turn_3eb43130091244be93803447be8d48b4", "session_id": "session_692afd19c6ac4d4a8b1c535168bdb40e", "sequence": 90}, {"request_id": "dialogue-91", "events": [{"role": "user", "content": "Caroline: Cool, thanks Mel! Can't wait. I'll keep ya posted. Bye!", "speaker": "Caroline", "occurred_at": "2023-07-03T13:36:00Z", "source_utc_offset_minutes": 0}], "turn_id": "turn_ee8c58f00a874ef185b0c18c7cdf653b", "session_id": "session_692afd19c6ac4d4a8b1c535168bdb40e", "sequence": 91}, {"request_id": "dialogue-92", "events": [{"role": "user", "content": "Melanie: Bye, Caroline! Can't wait to hear about it. Have fun and stay safe!", "speaker": "Melanie", "occurred_at": "2023-07-03T13:36:00Z", "source_utc_offset_minutes": 0}], "turn_id": "turn_14c97e4c9a274a7da5922ff1a40cc520", "session_id": "session_692afd19c6ac4d4a8b1c535168bdb40e", "sequence": 92}]
